        cz(1, "Escribí el Präteritum de *lesen*.", "Mein Vater ___ jeden Abend die Zeitung.", "las", note="*lesen – las – gelesen*."),
        tr(1, "En nuestro pueblo había un solo cine.", "In unserem Dorf gab es nur ein Kino.", ["In unserem Dorf gab es nur ein Kino.", "Es gab in unserem Dorf nur ein Kino."], "*es gab* = había."),
        tr(1, "Ella vivía en Viena.", "Sie wohnte in Wien.", ["Sie wohnte in Wien.", "Sie lebte in Wien.", "Sie hat in Wien gewohnt.", "Sie hat in Wien gelebt."], "Regular: *wohnte*. (Hablando, también Perfekt.)"),
