        ch(2, "Elegí el conector.", "___ ich klein war, hatte ich einen Hund.", "Als", ["Als", "Wenn", "Wann"], "Un período del pasado: *als*."),
        ch(2, "Elegí el conector.", "Immer ___ wir Ferien hatten, fuhren wir ans Meer.", "wenn", ["wenn", "als", "wann"], "Se repetía («cada vez que»): *wenn*."),
        ch(2, "Elegí el conector.", "___ ich nach Deutschland kam, sprach ich kein Wort Deutsch.", "Als", ["Als", "Wenn", "Wann"], "Una sola vez en el pasado: *als*."),
        ch(2, "Elegí el conector.", "___ ich morgen Zeit habe, rufe ich dich an.", "Wenn", ["Wenn", "Als", "Wann"], "Futuro: siempre *wenn*."),
        ch(2, "Elegí el conector.", "Weißt du, ___ der Zug kommt?", "wann", ["wann", "wenn", "als"], "Pregunta (aunque sea indirecta): *wann*."),
        ch(2, "Elegí el orden correcto.", "(Cuando llegamos, llovía.)", "Als wir ankamen, regnete es.", ["Als wir ankamen, regnete es.", "Als wir ankamen, es regnete.", "Als wir kamen an, regnete es."], "Separable junto al final, después verbo de la principal."),
        ch(2, "Elegí la forma correcta.", "«Me crié en Rosario.»", "Ich bin in Rosario aufgewachsen.", ["Ich bin in Rosario aufgewachsen.", "Ich habe in Rosario aufgewachsen.", "Ich bin in Rosario gewachsen."], "*aufwachsen* va con *sein* en el Perfekt."),
        cz(2, "Escribí *als* o *wenn*.", "___ meine Schwester auf die Welt kam, war ich drei Jahre alt.", "Als", note="Pasó una vez: *als*."),
        cz(2, "Escribí *als* o *wenn*.", "Jedes Mal, ___ es schneite, bauten wir einen Schneemann.", "wenn", note="*jedes Mal* → *wenn*."),
